from pathlib import Path
def edit(p,a,b):
    s=Path(p).read_text(encoding='utf-8-sig')
    if a not in s:raise RuntimeError(p+' '+a[:60])
    Path(p).write_text(s.replace(a,b),encoding='utf-8')
