edit('game.js',"function drawUI(key,x,y,width,height=width){const image=uiBitmap(key);", "function drawUI(key,x,y,width,height=width){const match=key.match(/^(badge-health|building-health-(?:Green|Red|Blue|Purple))-(\\d+)\\.svg$/),atlas=match&&healthAtlases.get(match[1]);if(atlas?.ready){const n=Number(match[2])-1;ctx.drawImage(atlas.canvas,(n%10)*atlas.w,Math.floor(n/10)*atlas.h,atlas.w,atlas.h,x-width/2,y-height/2,width,height);return;}const image=uiBitmap(key);")
edit('game.js',"function syncCanvasResolution()", "function prepareHealthAtlas(prefix,w,h){if(healthAtlases.has(prefix))return;const canvas=document.createElement('canvas');canvas.width=w*10;canvas.height=h*10;const item={canvas,w,h,ready:false};healthAtlases.set(prefix,item);Promise.all(Array.from({length:100},(_,i)=>new Promise(resolve=>{const image=uiBitmap(prefix+'-'+(i+1)+'.svg');const done=()=>{if(image.naturalWidth)canvas.getContext('2d').drawImage(image,(i%10)*w,Math.floor(i/10)*h,w,h);resolve(!!image.naturalWidth);};if(image.complete)done();else{image.addEventListener('load',done,{once:true});image.addEventListener('error',()=>resolve(false),{once:true});}}))).then(ok=>item.ready=ok.every(Boolean));}\nfunction syncCanvasResolution()")
